function applyMaterial(object, material, renderOrder = 0) {
  object.traverse((child) => {
    if (child.isMesh) {
      child.material = material;
      child.renderOrder = renderOrder;
    }
  });
}

async function createBodyScene({ THREE, scene, studio }) {
  const root = new THREE.Group();
  scene.add(root);
  if (studio?.pedestal) studio.pedestal.position.y = -1.78;

  const [torsoGlb, heartGlb, lungGlb, liverGlb, pancreasGlb, kidneysGlb, tracheaGlb] =
    await Promise.all([
      loadAnatomicalGLB("/media/models/torso.glb"),
      loadAnatomicalGLB("/media/models/heart.glb"),
      loadAnatomicalGLB("/media/models/lung.glb"),
      loadAnatomicalGLB("/media/models/liver.glb"),
      loadAnatomicalGLB("/media/models/pancreas.glb"),
      loadAnatomicalGLB("/media/models/kidneys.glb"),
      loadAnatomicalGLB("/media/models/trachea.glb"),
    ]);

  // 1. Translucent Fresnel-rim anatomical human torso bust (NIH HuBMAP skin-male)
  const torsoMat = makeFresnelShell(THREE, {
    rimColor: 0x387985,
    coreColor: 0xe3f0f4,
    rimPower: 2.15,
    rimStrength: 0.54,
    baseOpacity: 0.05,
    side: THREE.FrontSide,
  });
  applyMaterial(torsoGlb, torsoMat, 10);
  root.add(torsoGlb);

  // 2. Subtle anatomical trachea + larynx cartilage anchor
  const tracheaMat = makeCeramic(THREE, 0xd9e6ea, {
    transparent: true,
    opacity: 0.56,
    roughness: 0.42,
    clearcoat: 0.35,
  });
  applyMaterial(tracheaGlb, tracheaMat, 1);
  root.add(tracheaGlb);

  const organEntries = new Map();

  const registerOrgan = (id, group, materials, { baseOpacity = 0.72, activeOpacity = 0.96, inactiveOpacity = 0.44, pivot = null } = {}) => {
    tagPickable(group, id);
    root.add(group);
    organEntries.set(id, {
      group,
      materials: Array.isArray(materials) ? materials : [materials],
      baseOpacity,
      activeOpacity,
      inactiveOpacity,
      pivot: pivot ? new THREE.Vector3(...pivot) : null,
    });
  };

  // 3. Thyroid: sculpted organic butterfly lobes hugging upper NIH trachea
  {
    const mat = makeOrganMaterial(THREE, PALETTE.coral, {
      roughness: 0.28,
      clearcoat: 0.72,
      opacity: 0.94,
    });
    const thyroid = createOrganicThyroid(THREE, mat);
    thyroid.position.set(-0.015, 1.24, 0.245);
    registerOrgan("thyroid", thyroid, mat, { activeOpacity: 0.98, inactiveOpacity: 0.56 });
  }

  // 4. Lungs: translucent outer lobes + glowing deeper-teal internal bronchial tree
  {
    const lobeMat = makeOrganMaterial(THREE, PALETTE.tealLight, {
      roughness: 0.26,
      clearcoat: 0.75,
      opacity: 0.42,
      depthWrite: false,
    });
    const bronchiMat = makeOrganMaterial(THREE, PALETTE.tealDeep, {
      roughness: 0.34,
      clearcoat: 0.55,
      opacity: 0.72,
    });
    lungGlb.traverse((child) => {
      if (!child.isMesh) return;
      if (/bronchi/i.test(child.name)) {
        child.material = bronchiMat;
        child.renderOrder = 2;
      } else {
        child.material = lobeMat;
        child.renderOrder = 5;
      }
    });
    registerOrgan("lung", lungGlb, [lobeMat, bronchiMat], {
      activeOpacity: 0.72,
      inactiveOpacity: 0.28,
    });
  }

  // 5. Heart: real 4-chamber NIH heart nestled between the lungs
  {
    const venousMat = makeOrganMaterial(THREE, 0xb85258, {
      roughness: 0.28,
      clearcoat: 0.75,
      opacity: 0.94,
    });
    const arterialMat = makeOrganMaterial(THREE, PALETTE.arterial, {
      roughness: 0.26,
      clearcoat: 0.78,
      opacity: 0.96,
    });
    heartGlb.traverse((child) => {
      if (!child.isMesh) return;
      child.material = /right/i.test(child.name) ? venousMat : arterialMat;
      child.renderOrder = 3;
    });
    // Wrap heart around its own anatomical centroid so heartbeat scales cleanly in place
    const heartPivot = new THREE.Group();
    const hc = new THREE.Vector3(0.112, 0.307, 0.195);
    heartGlb.position.sub(hc);
    heartPivot.position.copy(hc);
    heartPivot.add(heartGlb);
    registerOrgan("heart", heartPivot, [venousMat, arterialMat], {
      activeOpacity: 0.98,
      inactiveOpacity: 0.58,
    });
  }

  // 6. Liver: real NIH right & left wedge lobes
  {
    const mat = makeOrganMaterial(THREE, PALETTE.liver, {
      roughness: 0.32,
      clearcoat: 0.65,
      opacity: 0.92,
    });
    applyMaterial(liverGlb, mat, 3);
    registerOrgan("liver", liverGlb, mat, { activeOpacity: 0.97, inactiveOpacity: 0.46 });
  }

  // 7. Pancreas: real NIH head/body/tail behind liver/stomach plane
  {
    const mat = makeOrganMaterial(THREE, PALETTE.gold, {
      roughness: 0.32,
      clearcoat: 0.62,
      opacity: 0.94,
    });
    applyMaterial(pancreasGlb, mat, 3);
    registerOrgan("pancreas", pancreasGlb, mat, { activeOpacity: 0.98, inactiveOpacity: 0.5 });
  }

  // 8. Paired Kidneys: real NIH asymmetric left & right retroperitoneal kidneys
  {
    const mat = makeOrganMaterial(THREE, PALETTE.venous, {
      roughness: 0.28,
      clearcoat: 0.7,
      opacity: 0.94,
    });
    applyMaterial(kidneysGlb, mat, 3);
    registerOrgan("kidney", kidneysGlb, mat, { activeOpacity: 0.98, inactiveOpacity: 0.54 });
  }

  let prevFocus = null;
  const pinAnchor = new THREE.Vector3();

  return {
    getPins(state) {
      if (state?.compact) return [];
      const activeId = state?.activeId || "heart";
      const meta = ORGANS_META.find((o) => o.id === activeId);
      if (!meta) return [];
      pinAnchor.set(...meta.pos).applyMatrix4(root.matrixWorld);
      return [
        {
          id: "active-organ",
          pos: [pinAnchor.x, pinAnchor.y, pinAnchor.z],
          title: meta.name,
          subtitle: meta.shortTests,
          tone: meta.tone,
          active: true,
        },
      ];
    },
    update(state, dt, elapsed, reducedMotion, glideTo) {
      const activeId = state?.activeId || "heart";
      if (state?.autoFocus && activeId !== prevFocus) {
        prevFocus = activeId;
        const meta = ORGANS_META.find((o) => o.id === activeId);
        if (meta && glideTo) glideTo(meta.cam, meta.pos);
      }
      if (!reducedMotion && state?.autoRotate) {
        root.rotation.y += dt * 0.24;
      }

      for (const [id, entry] of organEntries.entries()) {
        const isActive = id === activeId;
        entry.materials.forEach((mat, idx) => {
          // Keep internal bronchial tree slightly stronger when lung is focused
          const targetOpacity = isActive
            ? (id === "lung" && idx === 1 ? 0.95 : entry.activeOpacity)
            : (id === "lung" && idx === 1 ? 0.36 : entry.inactiveOpacity);
          const targetEmissive = isActive ? 0.32 : 0.05;
          mat.opacity += (targetOpacity - mat.opacity) * 0.14;
          mat.emissiveIntensity += (targetEmissive - mat.emissiveIntensity) * 0.14;
        });

        if (id === "heart") {
          // Realistic subtle physiological cardiac lub-dub pulse
          const phase = (elapsed * 1.15) % 1;
          const lub = Math.exp(-Math.pow((phase - 0.12) / 0.055, 2));
          const dub = 0.45 * Math.exp(-Math.pow((phase - 0.26) / 0.05, 2));
          const beat = reducedMotion ? 1 : 1 + (lub + dub) * (isActive ? 0.048 : 0.025);
          entry.group.scale.setScalar(beat);
        }
      }
      root.updateMatrixWorld(true);
    },
  };
}

export default function BodyMap3D({
  activeId: initialId,
  onSelect,
  availableIds = null,
  compact = false,
}) {
  const [selectedId, setSelectedId] = useState(
    initialId && ORGANS_META.some((o) => o.id === initialId) ? initialId : "heart",
  );
  useEffect(() => {
    if (initialId && ORGANS_META.some((o) => o.id === initialId)) {
      setSelectedId(initialId);
    }
  }, [initialId]);

  const items = useMemo(
    () => (availableIds ? ORGANS_META.filter((o) => availableIds.includes(o.id)) : ORGANS_META),
    [availableIds],
  );
  const current = items.find((o) => o.id === selectedId) || items[0] || ORGANS_META[0];
  const [autoFocus, setAutoFocus] = useState(false);

  const buildScene = useCallback((ctx) => createBodyScene(ctx), []);

  const choose = (id) => {
    setSelectedId(id);
    setAutoFocus(true);
  };

  if (compact) {
    return (
      <div className="tour-3d-wrap">
        <ThreeStage
          ariaLabel="3D 透明人体六大器官真实解剖位置示意"
          badge="3D 真实解剖透视"
          hint="拖拽旋转躯干 · 点击器官查看位置"
          attribution={HUBMAP_ATTRIBUTION}
          cameraPosition={[0, 0.15, 5.1]}
          cameraTarget={[0, 0.05, 0]}
          buildScene={buildScene}
          sceneState={{ activeId: current.id, autoFocus: false, autoRotate: true, compact: true }}
          onPick={choose}
        />
      </div>
    );
  }

  return (
    <div className="body-map-grid">
      <ThreeStage
        className="body-map-stage"
        ariaLabel="3D 透明人体六大器官真实解剖位置示意"
        badge="3D 真实解剖透视 · NIH HRA"
        hint="拖拽 360° 旋转透明人体 · 点击发光器官或下方标签切换聚焦视角"
        attribution={HUBMAP_ATTRIBUTION}
        cameraPosition={[0, 0.1, 5.75]}
        cameraTarget={[0, 0.04, 0]}
        buildScene={buildScene}
        sceneState={{ activeId: current.id, autoFocus, autoRotate: false, compact: false }}
        onPick={choose}
      />
      <div className="body-map-info" aria-live="polite">
        <div className="body-map-pills" role="group" aria-label="选择器官位置">
          {items.map((item) => (
            <button
              key={item.id}
              type="button"
              className={current.id === item.id ? "active" : ""}
              onClick={() => choose(item.id)}
            >
              {item.name}
            </button>
          ))}
        </div>
        <h3>{current.name}</h3>
        <span className="body-map-connection">解剖位置：{current.region}</span>
        <p>{current.role}</p>
        <span className="body-map-connection">对应常见体检：{current.tests}</span>
        {onSelect ? (
          <RouteLink page="organs" id={current.id} className="text-link" onNavigate={() => onSelect(current.id)}>
            进入{current.name}专题 <ArrowRight size={15} aria-hidden="true" />
          </RouteLink>
        ) : null}
        <p className="concept-3d-note">
          <b>图示边界：</b>躯干与心肺肝胰肾三维网格源自美国 NIH HuBMAP 标准成人参考解剖图谱（CC BY 4.0），甲状腺为结合真实气管位置构建的科普形态；仅用于理解器官相对方位，不代表个人解剖差异或影像检查结果。
        </p>
      </div>
    </div>
  );
}
